          74: "오른 주먹의 1·2지를 펴서 구부려 끝을 오른쪽 볼에 댄 다음, 손끝을 맞대고 끝이 위로 등이 밖으로 향하게 세운 왼손의 손끝에 4·3·2·1지 순으로 오른손의 1·5지 끝을 맞댔다 뗀다.",
