          44: "5지를 접고 1·2·3·4지를 편 왼손을 모로 세우고, 오른손의 손가락을 약간 구부려 왼손의 1지에 걸었다가 오른쪽으로 약간 이동하여 다시 건다.",
          45: "[결합: 영어 지문자 ‘W’/영어 지문자 ‘C’] 오른손을 펴서 손바닥이 밖으로 향하게 세워 2·3·4지를 벌리고 1·5지를 ‘C’자 모양으로 구부린다.",
          46: "두 손의 1지 끝을 포개어 오른쪽 귀 가까이에 대고 5지 바닥에 2지를 두 번 튕겨 편다.",
          47: "오른팔을 세워 팔꿈치를 왼 손바닥으로 받치고, 오른손을 손바닥이 밖으로 향하게 벌려 약간 구부려 좌우로 돌린다.",
          48: "두 손의 손바닥과 손끝을 위로 향하게 하여 배 앞에 나란히 놓았다가 배 쪽으로 두 번 당긴다.",
          49: "오른손을 약간 구부려 끝이 밖으로 향하게 하여 5지 등을 손등이 위로 손끝이 오른쪽으로 향하게 편 왼 손등에 대고 좌우로 두 번 움직인다.",
          50: "오른손으로 ‘⊃’모양을 만들어, 손등이 위로 손끝이 오른쪽으로 향하게 편 왼 손등에 올려 놓고 좌우로 두 번 이동시킨 다음, 손끝이 오른쪽으로 손바닥이 위로 향하게 편 왼 손바닥에, 손끝이 왼쪽으로 손등이 위로 향하게 편 오른손을 댔다가 손등이 밖으로 향하게 돌린다.",
          51: "오른 주먹을 들어 팔을 세우고 팔꿈치를 왼 손바닥에 올려놓는다.",
          52: "두 주먹을 가슴 앞으로 올려 떠는 동작을 한 다음, 왼손을 손바닥이 밖으로 향하게 세우고 그 오른쪽에서 오른 주먹을 오른쪽으로 당긴다.",
          53: "두 주먹을 가슴 앞으로 올려 떠는 동작을 한 다음, 1·2·5지를 약간 구부린 두 주먹을 모로 세워 오른 주먹을 왼 주먹 약간 뒤에 놓고 동시에 상하로 흔든다.",
          54: "손바닥이 위로 손끝이 오른쪽으로 향하게 편 왼 손바닥에 오른 주먹을 바닥이 닿게 올려놓고 좌우로 움직인다.",
          55: "두 손의 손끝을 맞대어 좌우로 비스듬히 세운 다음, 왼손은 그대로 두고, 오른손은 주먹을 쥐고 4·5지를 펴서 세워 손목을 좌우로 약간 흔들며 오른쪽으로 약간 이동한다.",
